const countNonSphinxTypes = (army: Card[]): number => {
  const types = new Set(army.map((card) => card.monster));
  types.delete(SPHINX);
  return types.size;
};

const TYPES_BEFORE_BONUS = 3;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  return countNonSphinxTypes(army) > TYPES_BEFORE_BONUS ? 3 : 2;
};
